reynolds-number-pipe-flow-friction-facto.js:
(() => {
  'use strict';
  const vEl = document.getElementById('rn-v'), dEl = document.getElementById('rn-d');
  const rhoEl = document.getElementById('rn-rho'), muEl = document.getElementById('rn-mu');
  const reResEl = document.getElementById('rn-res-re'), fResEl = document.getElementById('rn-res-f');

  function update() {
    const v = parseFloat(vEl.value), D = parseFloat(dEl.value);
    const rho = parseFloat(rhoEl.value), mu = parseFloat(muEl.value);

    if (isNaN(v) || isNaN(D) || isNaN(rho) || isNaN(mu) || v <= 0 || D <= 0 || rho <= 0 || mu <= 0) return;

    // Reynolds Number: Re = ( rho * v * D ) / mu
    const Re = (rho * v * D) / mu;

    let regime = '', f = 0, color = '#22543d';
    if (Re < 2300) {
      regime = 'LAMINAR FLOW (Re < 2,300)';
      f = 64.0 / Re;
      color = '#22543d';
    } else if (Re <= 4000) {
      regime = 'TRANSITIONAL FLOW (2,300 ≤ Re ≤ 4,000)';
      f = 0.035;
      color = '#ea580c';
    } else {
      regime = 'TURBULENT FLOW (Re > 4,000)';
      // Blasius formula for smooth pipes: f = 0.3164 * Re^(-0.25)
      f = 0.3164 * Math.pow(Re, -0.25);
      color = '#22543d';
    }

    // Darcy-Weisbach head loss per meter: h_f/L = f * (v^2) / (2 * g * D)
    const g = 9.80665;
    const hf_per_L = f * (Math.pow(v, 2) / (2.0 * g * D));

    reResEl.textContent = 'Re = ' + Math.round(Re).toLocaleString() + ' (' + regime.split(' (')[0] + ')';
    reResEl.style.color = color;
    fResEl.textContent = 'Darcy Friction f = ' + f.toFixed(4) + ' | Unit Head Loss h_f/L = ' + hf_per_L.toFixed(3) + ' m/m (' + regime + ')';
  }

  [vEl, dEl, rhoEl, muEl].forEach(el => el.addEventListener('input', update));
  update();
})();

(() => {
  'use strict';
  const vEl = document.getElementById('re-v'), dEl = document.getElementById('re-d');
  const rhoEl = document.getElementById('re-rho'), muEl = document.getElementById('re-mu');
  const reResEl = document.getElementById('re-res-val'), fResEl = document.getElementById('re-res-f');

  function update() {
    const v = parseFloat(vEl.value), D_mm = parseFloat(dEl.value);
    const rho = parseFloat(rhoEl.value), mu_mPas = parseFloat(muEl.value);

    if (isNaN(v) || isNaN(D_mm) || isNaN(rho) || isNaN(mu_mPas) || v <= 0 || D_mm <= 0 || rho <= 0 || mu_mPas <= 0) return;

    const D = D_mm / 1000.0;
    const mu = mu_mPas / 1000.0;

    // Reynolds number: Re = ( rho * v * D ) / mu
    const Re = (rho * v * D) / mu;

    let f = 0, regime = '';
    let color = '#22543d';

    if (Re < 2300) {
      // Laminar: f = 64 / Re
      f = 64.0 / Re;
      regime = 'LAMINAR FLOW (Re < 2,300: Smooth streamline viscous flow, f = 64/Re)';
      color = '#22543d';
    } else if (Re <= 4000) {
      // Transitional
      f = 0.035;
      regime = 'TRANSITIONAL REGIME (2,300 ≤ Re ≤ 4,000: Intermittent turbulent bursts)';
      color = '#d97706';
    } else {
      // Turbulent Swamee-Jain for smooth pipe (epsilon = 0.0015 mm commercial steel):
      const eps_over_D = 0.000045 / D; // 0.045 mm commercial steel roughness
      f = 0.25 / Math.pow(Math.log10((eps_over_D / 3.7) + (5.74 / Math.pow(Re, 0.9))), 2);
      regime = 'FULLY TURBULENT (Re > 4,000: Chaotic vortex mixing & high momentum transfer)';
      color = '#2563eb';
    }

    reResEl.textContent = 'Re = ' + Math.round(Re).toLocaleString() + ' (' + regime.split(' (')[0] + ')';
    reResEl.style.color = color;
    fResEl.textContent = 'Darcy Friction Factor f = ' + f.toFixed(4) + ' | ' + regime;
    fResEl.style.color = color;
  }

  [vEl, dEl, rhoEl, muEl].forEach(el => el.addEventListener('input', update));
  update();
})();

rf-amplifier-noise-figure-cascaded-friis.js:
(function() {
  'use strict';
  var slug = 'rf-amplifier-noise-figure-cascaded-friis-noise-calculator';

  function el(id) {
    return document.getElementById(slug + '-' + id);
  }

  var outputEl = document.getElementById(slug + '-output');
  var msgEl = document.getElementById(slug + '-message');
  var btn = document.getElementById('primary-action-btn');
  var copyBtn = document.getElementById('copy-output');
  var clearBtn = document.getElementById('clear-text');

  function setMsg(t, err) {
    msgEl.textContent = t;
    msgEl.classList.toggle('is-error', !!err);
  }

  function calculate() {
    try {

      var g1 = parseFloat(el('g1-db').value);
      var nf1 = parseFloat(el('nf1-db').value);
      var g2 = parseFloat(el('g2-db').value);
      var nf2 = parseFloat(el('nf2-db').value);
      var g3 = parseFloat(el('g3-db').value);
      var nf3 = parseFloat(el('nf3-db').value);
      if ([g1, nf1, g2, nf2, g3, nf3].some(isNaN)) {
        return { err: 'Please enter valid numerical values for all stage gains and noise figures.' };
      }
      var f1 = Math.pow(10, nf1 / 10);
      var f2 = Math.pow(10, nf2 / 10);
      var f3 = Math.pow(10, nf3 / 10);
      var g1_lin = Math.pow(10, g1 / 10);
      var g2_lin = Math.pow(10, g2 / 10);
      var f_sys = f1 + ((f2 - 1) / g1_lin) + ((f3 - 1) / (g1_lin * g2_lin));
      var nf_sys = 10 * Math.log10(f_sys);
      var g_sys = g1 + g2 + g3;
      var out = 'CASCADED RF NOISE FIGURE (FRIIS FORMULA) ANALYSIS\n';
      out += '================================================\n';
      out += 'Stage 1: Gain = ' + g1 + ' dB, NF = ' + nf1 + ' dB\n';
      out += 'Stage 2: Gain = ' + g2 + ' dB, NF = ' + nf2 + ' dB\n';
      out += 'Stage 3: Gain = ' + g3 + ' dB, NF = ' + nf3 + ' dB\n\n';
      out += 'RESULTS:\n';
      out += 'Overall System Gain   : ' + g_sys.toFixed(2) + ' dB\n';
      out += 'Cascaded Noise Factor : ' + f_sys.toFixed(4) + '\n';
      out += 'Cascaded Noise Figure : ' + nf_sys.toFixed(2) + ' dB';
      return { out: out, msg: 'Cascaded noise figure computed successfully.' };

    } catch(e) {
      return { err: 'Error during calculation: ' + e.message };
    }
  }

  btn.addEventListener('click', function() {
    var res = calculate();
    if (res.err) {
      outputEl.value = '';
      copyBtn.disabled = true;
      setMsg(res.err, true);
    } else {
      outputEl.value = res.out;
      copyBtn.disabled = false;
      setMsg(res.msg || 'Calculation completed successfully.');
    }
  });

  copyBtn.addEventListener('click', function() {
    if (window.NikTool && typeof window.NikTool.copy === 'function') {
      window.NikTool.copy(outputEl.value, copyBtn);
    } else if (navigator.clipboard) {
      navigator.clipboard.writeText(outputEl.value);
    }
    setMsg('Result copied to clipboard.');
  });

  clearBtn.addEventListener('click', function() {
    var inputs = ['g1-db', 'nf1-db', 'g2-db', 'nf2-db', 'g3-db', 'nf3-db'];
    inputs.forEach(function(id) {
      var elem = el(id);
      if (elem) elem.value = elem.defaultValue || '';
    });
    outputEl.value = '';
    copyBtn.disabled = true;
    setMsg('Cleared. Enter values above.');
  });
})();

rf-cavity-shunt-impedance-q-factor-calcu.js:
(() => {
  'use strict';
  const vEl = document.getElementById('rfc-v'), rEl = document.getElementById('rfc-rs'), qEl = document.getElementById('rfc-q');
  const pResEl = document.getElementById('rfc-res-pwr'), rqResEl = document.getElementById('rfc-res-roq');

  function update() {
    const vMv = parseFloat(vEl.value), rsMohm = parseFloat(rEl.value), Q0 = parseFloat(qEl.value);
    if (isNaN(vMv) || isNaN(rsMohm) || isNaN(Q0) || vMv <= 0 || rsMohm <= 0 || Q0 <= 0) return;

    const vVolts = vMv * 1e6;
    const rsOhms = rsMohm * 1e6;
    const pWatts = (Math.pow(vVolts, 2)) / (2 * rsOhms);
    const pKw = pWatts / 1000;
    const roq = rsOhms / Q0;

    pResEl.textContent = pKw.toFixed(1) + ' kW Dissipated (' + (pKw >= 1000 ? (pKw / 1000).toFixed(2) + ' MW' : pKw.toFixed(1) + ' kW') + ')';
    rqResEl.textContent = 'R / Q = ' + roq.toFixed(1) + ' Ω (Quality Factor Q₀ = ' + (Q0 >= 1e6 ? Q0.toExponential(1) : Math.round(Q0).toLocaleString()) + ')';
  }

  [vEl, rEl, qEl].forEach(el => el.addEventListener('input', update));
  update();
})();

