(() => {
  'use strict';
  const d1El = document.getElementById('rh-d1'), d2El = document.getElementById('rh-d2');
  const areaEl = document.getElementById('rh-res-area'), sideEl = document.getElementById('rh-res-side'), perEl = document.getElementById('rh-res-perim');

  function update() {
    const d1 = parseFloat(d1El.value), d2 = parseFloat(d2El.value);
    if (isNaN(d1) || isNaN(d2) || d1 <= 0 || d2 <= 0) return;

    const area = 0.5 * d1 * d2;
    // Side length by Pythagorean theorem on 4 right triangles: s = sqrt((d1/2)^2 + (d2/2)^2)
    const side = Math.sqrt(Math.pow(d1 / 2, 2) + Math.pow(d2 / 2, 2));
    const perim = 4 * side;

    areaEl.textContent = area.toFixed(2) + ' sq units';
    sideEl.textContent = side.toFixed(2) + ' units';
    perEl.textContent = perim.toFixed(2) + ' units';
  }

  d1El.addEventListener('input', update);
  d2El.addEventListener('input', update);
  update();
})();

rhumb-line-loxodrome-distance-bearing-ca.js:
(() => {
  'use strict';
  const lat1El = document.getElementById('rl-lat1'), lon1El = document.getElementById('rl-lon1');
  const lat2El = document.getElementById('rl-lat2'), lon2El = document.getElementById('rl-lon2');
  const hdgResEl = document.getElementById('rl-res-hdg'), dstResEl = document.getElementById('rl-res-dist');

  const R_Earth_km = 6371.0;
  function toRad(deg) { return (deg * Math.PI) / 180; }

  function update() {
    const lat1 = parseFloat(lat1El.value), lon1 = parseFloat(lon1El.value);
    const lat2 = parseFloat(lat2El.value), lon2 = parseFloat(lon2El.value);

    if (isNaN(lat1) || isNaN(lon1) || isNaN(lat2) || isNaN(lon2)) return;

    const phi1 = toRad(lat1), phi2 = toRad(lat2);
    const dPhi = phi2 - phi1;
    let dLam = toRad(lon2 - lon1);

    // Projected latitude change on Mercator chart: dPsi = ln( tan(pi/4 + phi2/2) / tan(pi/4 + phi1/2) )
    const dPsi = Math.log(Math.tan(Math.PI / 4 + phi2 / 2) / Math.tan(Math.PI / 4 + phi1 / 2));

    // Wrap delta longitude between -pi and +pi
    if (Math.abs(dLam) > Math.PI) {
      dLam = dLam > 0 ? -(2 * Math.PI - dLam) : (2 * Math.PI + dLam);
    }

    // Bearing theta = atan2(dLam, dPsi)
    const bearingRad = Math.atan2(dLam, dPsi);
    let bearingDeg = (bearingRad * 180) / Math.PI;
    bearingDeg = (bearingDeg + 360) % 360;

    // Distance q = dPhi / dPsi (or cos(phi1) if dPsi -> 0 along parallel)
    const q = Math.abs(dPsi) > 1e-10 ? dPhi / dPsi : Math.cos(phi1);
    const distKm = Math.sqrt(dPhi * dPhi + q * q * dLam * dLam) * R_Earth_km;
    const distNm = distKm * 0.539957;

    hdgResEl.textContent = bearingDeg.toFixed(1) + '° True Heading';
    dstResEl.textContent = Math.round(distKm).toLocaleString() + ' km (' + Math.round(distNm).toLocaleString() + ' NM Sailing Distance)';
  }

  [lat1El, lon1El, lat2El, lon2El].forEach(el => el.addEventListener('input', update));
  update();
})();

richardson-number-atmospheric-turbulence.js:
(() => {
  'use strict';
  const thEl = document.getElementById('ri-theta'), dtEl = document.getElementById('ri-dtdz'), duEl = document.getElementById('ri-dudz');
  const riResEl = document.getElementById('ri-res-val'), catResEl = document.getElementById('ri-res-cat');

  const g = 9.80665;

  function update() {
    const theta = parseFloat(thEl.value), dtheta_km = parseFloat(dtEl.value), du_km = parseFloat(duEl.value);
    if (isNaN(theta) || isNaN(dtheta_km) || isNaN(du_km) || theta <= 0 || du_km <= 0) return;

    // Convert gradients per km to per meter: divide by 1000
    const dtheta_dz = dtheta_km / 1000.0;
    const du_dz = du_km / 1000.0;

    // Brunt-Vaisala frequency squared N^2 = (g / theta) * dtheta_dz  [s^-2]
    const N2 = (g / theta) * dtheta_dz;
    // Wind shear squared S^2 = (du_dz)^2  [s^-2]
    const S2 = Math.pow(du_dz, 2);

    // Richardson number Ri = N^2 / S^2
    const Ri = N2 / S2;

    let status = '';
    let color = '#22543d';

    if (Ri < 0) {
      status = 'STATICALLY UNSTABLE (Ri < 0: Buoyancy driven convective overturning & thermal plumes)';
      color = '#c53030';
    } else if (Ri <= 0.25) {
      status = 'ACTIVE CLEAR AIR TURBULENCE (Ri ≤ 0.25: Kelvin-Helmholtz billow waves break into severe turbulence!)';
      color = '#c53030';
    } else if (Ri <= 1.0) {
      status = 'MARGINALLY STABLE (0.25 < Ri ≤ 1.0: Existing turbulence may persist)';
      color = '#d97706';
    } else {
      status = 'LAMINAR / STABLE AIR (Ri > 1.0: Strong thermal stratification completely suppresses turbulence)';
      color = '#22543d';
    }

    riResEl.textContent = 'Ri = ' + Ri.toFixed(3) + ' (' + (Ri <= 0.25 ? 'Turbulent' : 'Stable') + ')';
    riResEl.style.color = color;
    catResEl.textContent = status + ' | N² = ' + N2.toExponential(2) + ' s⁻², Shear S = ' + du_dz.toFixed(3) + ' s⁻¹';
    catResEl.style.color = color;
  }

  [thEl, dtEl, duEl].forEach(el => el.addEventListener('input', update));
  update();
})();

