      fResEl.textContent = 'MARGINALLY STABLE (0.25 ≤ Ri < 1.0: Intermittent shear wave breaking)';
      fResEl.style.color = '#d97706';
    } else {
      fResEl.textContent = 'STRONGLY STRATIFIED STABLE (Ri ≥ 1.0: Stable pycnocline, turbulent mixing suppressed)';
      fResEl.style.color = '#22543d';
    }
  }

  nEl.addEventListener('input', update);
  sEl.addEventListener('input', update);
  update();
})();

richter-magnitude-earthquake-seismic-ene.js:
(() => {
  'use strict';
  const mEl = document.getElementById('eq-m');
  const eResEl = document.getElementById('eq-res-e'), tntResEl = document.getElementById('eq-res-tnt');

  function update() {
    const M = parseFloat(mEl.value);
    if (isNaN(M) || M < 1.0 || M > 10.0) return;

    // Gutenberg-Richter energy formula: log10(E) = 4.8 + 1.5 * M  [Joules]
    const logE = 4.8 + (1.5 * M);
    const E_joules = Math.pow(10, logE);

    // 1 ton of TNT = 4.184 x 10^9 Joules
    const tons_tnt = E_joules / 4.184e9;

    let tntStr = '';
    if (tons_tnt >= 1e6) tntStr = (tons_tnt / 1e6).toFixed(2) + ' Megatons TNT';
    else if (tons_tnt >= 1000) tntStr = Math.round(tons_tnt / 1000) + ' Kilotons TNT';
    else tntStr = Math.round(tons_tnt) + ' Tons TNT';

    eResEl.textContent = 'E = ' + E_joules.toExponential(2) + ' Joules';
    tntResEl.textContent = 'TNT Equivalent = ' + tntStr + ' (Magnitude ' + M.toFixed(1) + ' | 31.62× energy per +1.0 step)';
  }

  mEl.addEventListener('input', update);
  update();
})();

ricker-wavelet-seismic-peak-frequency-re.js:
(() => {
  'use strict';
  const fpEl = document.getElementById('rw-fp'), vEl = document.getElementById('rw-v');
  const tnResEl = document.getElementById('rw-res-tune'), tmResEl = document.getElementById('rw-res-time');

  function update() {
    const f_p = parseFloat(fpEl.value), v = parseFloat(vEl.value);
    if (isNaN(f_p) || isNaN(v) || f_p <= 0 || v <= 0) return;

    // Dominant seismic wavelength: lambda = v / f_p  [m]
    const lambda = v / f_p;

    // Rayleigh quarter-wavelength tuning thickness limit: z_tune = lambda / 4 = v / (4 * f_p)
    const z_tune = lambda / 4.0;

    // Ricker wavelet peak-to-trough time separation: Delta_t = sqrt(6) / (2 * pi * f_p)  [s -> ms]
    const delta_t_s = Math.sqrt(6.0) / (2.0 * Math.PI * f_p);
    const delta_t_ms = delta_t_s * 1000.0;

    tnResEl.textContent = 'Tuning Limit = ' + z_tune.toFixed(1) + ' m (λ / 4)';
    tmResEl.textContent = 'Wavelength λ = ' + lambda.toFixed(1) + ' m | Peak-to-Trough Δt = ' + delta_t_ms.toFixed(1) + ' ms (f_p = ' + f_p + ' Hz @ ' + v + ' m/s)';
  }

  fpEl.addEventListener('input', update);
  vEl.addEventListener('input', update);
  update();
})();

rl-circuit-current-growth-decay-time-con.js:
(() => {
  'use strict';
  const lEl = document.getElementById('rl-ind2'), rEl = document.getElementById('rl-res2');
  const v0El = document.getElementById('rl-v02'), tEl = document.getElementById('rl-t2');
  const tauResEl = document.getElementById('rl-res-tau2'), itResEl = document.getElementById('rl-res-it');

  function update() {
    const L_mH = parseFloat(lEl.value), R = parseFloat(rEl.value);
    const V0 = parseFloat(v0El.value), t_ms = parseFloat(tEl.value);

    if (isNaN(L_mH) || isNaN(R) || isNaN(V0) || isNaN(t_ms) || L_mH <= 0 || R <= 0 || V0 <= 0 || t_ms < 0) return;

    const L = L_mH / 1000.0;
    const t_s = t_ms / 1000.0;

    // Time constant tau = L / R  [seconds]
    const tau_s = L / R;
    const tau_ms = tau_s * 1000.0;

    // Steady state maximum current I_max = V0 / R  [Amperes]
    const I_max = V0 / R;

    // Current growth: I(t) = I_max * ( 1 - exp(-t / tau) )
    const I_t = I_max * (1.0 - Math.exp(-t_s / tau_s));
    const pct_I = (I_t / I_max) * 100.0;

    // Stored magnetic energy: U = 0.5 * L * I^2  [Joules]
    const U_mJ = 0.5 * L * Math.pow(I_t, 2) * 1000.0;

    tauResEl.textContent = 'Time Constant τ = ' + (tau_ms >= 1000 ? (tau_ms/1000).toFixed(2) + ' s' : tau_ms.toFixed(2) + ' ms');
    itResEl.textContent = 'Current I(t) = ' + I_t.toFixed(3) + ' A (' + pct_I.toFixed(1) + '% I_max = ' + I_max.toFixed(3) + ' A | Energy U = ' + U_mJ.toFixed(1) + ' mJ @ t = ' + t_ms + ' ms)';
  }

  [lEl, rEl, v0El, tEl].forEach(el => el.addEventListener('input', update));
  update();
})();

rlc-resonant-frequency-q-factor-calculat.js:
(() => {
  'use strict';
  const lEl = document.getElementById('rlc-l'), cEl = document.getElementById('rlc-c'), rEl = document.getElementById('rlc-r');
  const f0El = document.getElementById('rlc-res-f0'), qEl = document.getElementById('rlc-res-q'), bwEl = document.getElementById('rlc-res-bw');

  function update() {
    const lMh = parseFloat(lEl.value), cNf = parseFloat(cEl.value), R = parseFloat(rEl.value);
    if (isNaN(lMh) || isNaN(cNf) || isNaN(R) || lMh <= 0 || cNf <= 0 || R <= 0) return;

    const L = lMh * 1e-3;
    const C = cNf * 1e-9;

    // f0 = 1 / (2 * pi * sqrt(L * C))
    const f0 = 1 / (2 * Math.PI * Math.sqrt(L * C));
    // Q (series) = (1 / R) * sqrt(L / C)
    const Q = (1 / R) * Math.sqrt(L / C);
    // Bandwidth BW = f0 / Q
    const bw = f0 / Q;

    f0El.textContent = f0 >= 1e6 ? (f0 / 1e6).toFixed(3) + ' MHz' : (f0 >= 1e3 ? (f0 / 1e3).toFixed(2) + ' kHz' : f0.toFixed(1) + ' Hz');
    qEl.textContent = 'Q = ' + Q.toFixed(2);
    bwEl.textContent = bw >= 1e3 ? (bw / 1e3).toFixed(2) + ' kHz' : bw.toFixed(1) + ' Hz';
  }

  [lEl, cEl, rEl].forEach(el => el.addEventListener('input', update));
  update();
})();

rlc-resonant-frequency-quality-factor-ba.js:
(() => {
  'use strict';
  const lEl = document.getElementById('rl-ind'), cEl = document.getElementById('rl-cap'), rEl = document.getElementById('rl-res');
  const f0ResEl = document.getElementById('rl-res-f0'), qResEl = document.getElementById('rl-res-q');

  function update() {
    const L_uH = parseFloat(lEl.value), C_pF = parseFloat(cEl.value), R = parseFloat(rEl.value);
    if (isNaN(L_uH) || isNaN(C_pF) || isNaN(R) || L_uH <= 0 || C_pF <= 0 || R <= 0) return;

    const L = L_uH * 1e-6;
    const C = C_pF * 1e-12;

    // Resonant frequency: f0 = 1 / ( 2 * pi * sqrt(L * C) )  [Hz]
    const f0 = 1.0 / (2.0 * Math.PI * Math.sqrt(L * C));

    // Quality Factor Q = ( 1 / R ) * sqrt( L / C )
    const Q = (1.0 / R) * Math.sqrt(L / C);

    // Bandwidth BW = f0 / Q  [Hz]
    const BW = f0 / Q;

    let f0Str = '';
    if (f0 >= 1e6) f0Str = (f0 / 1e6).toFixed(3) + ' MHz';
    else if (f0 >= 1e3) f0Str = (f0 / 1e3).toFixed(2) + ' kHz';
    else f0Str = f0.toFixed(1) + ' Hz';

    let bwStr = '';
    if (BW >= 1e6) bwStr = (BW / 1e6).toFixed(2) + ' MHz';
    else if (BW >= 1e3) bwStr = (BW / 1e3).toFixed(2) + ' kHz';
    else bwStr = BW.toFixed(1) + ' Hz';

