    const J21 = (L1 * Math.cos(th1)) + (L2 * Math.cos(th12));
    const J22 = (L2 * Math.cos(th12));

    const tau1 = (J11 * Fx) + (J21 * Fy);
    const tau2 = (J12 * Fx) + (J22 * Fy);

    tResEl.textContent = 'τ₁ = ' + tau1.toFixed(2) + ' Nm | τ₂ = ' + tau2.toFixed(2) + ' Nm';
