rotational-kinetic-energy-moment-of-iner.js:
(() => {
  'use strict';
  const gEl = document.getElementById('rd-geom'), mEl = document.getElementById('rd-m');
  const rEl = document.getElementById('rd-r'), rpmEl = document.getElementById('rd-rpm');
  const krResEl = document.getElementById('rd-res-krot'), iResEl = document.getElementById('rd-res-i');

  function update() {
    const geom = gEl.value;
    const m = parseFloat(mEl.value), r = parseFloat(rEl.value), rpm = parseFloat(rpmEl.value);

    if (isNaN(m) || isNaN(r) || isNaN(rpm) || m <= 0 || r <= 0 || rpm < 0) return;

    // Moment of Inertia I:
    let I = 0;
    if (geom === 'cylinder') I = 0.5 * m * Math.pow(r, 2);
    else if (geom === 'sphere') I = 0.4 * m * Math.pow(r, 2);
    else if (geom === 'hoop') I = m * Math.pow(r, 2);
    else if (geom === 'rod') I = (1.0 / 12.0) * m * Math.pow(r, 2);

    // Angular velocity omega = RPM * 2*pi / 60  [rad / s]
    const omega = (rpm * 2.0 * Math.PI) / 60.0;

    // Rotational kinetic energy: K_rot = 0.5 * I * omega^2  [Joules]
    const K_rot_J = 0.5 * I * Math.pow(omega, 2);
    const K_rot_kJ = K_rot_J / 1000.0;

    // Angular momentum: L = I * omega  [kg * m^2 / s]
    const L_ang = I * omega;

    krResEl.textContent = 'Energy K_rot = ' + (K_rot_kJ >= 1 ? K_rot_kJ.toFixed(2) + ' kJ' : K_rot_J.toFixed(1) + ' J');
    iResEl.textContent = 'Inertia I = ' + I.toFixed(3) + ' kg·m² | Angular Momentum L = ' + L_ang.toFixed(1) + ' kg·m²/s (ω = ' + omega.toFixed(2) + ' rad/s @ ' + rpm + ' RPM)';
  }

  [gEl, mEl, rEl, rpmEl].forEach(el => el.addEventListener('input', update));
  gEl.addEventListener('change', update);
  update();
})();

rsa-cryptography-public-private-key-pair.js:
(() => {
  'use strict';
  const pEl = document.getElementById('rsa-p'), qEl = document.getElementById('rsa-q');
  const eEl = document.getElementById('rsa-e'), msgEl = document.getElementById('rsa-msg');
  const cResEl = document.getElementById('rsa-res-cipher'), kResEl = document.getElementById('rsa-res-keys');

  function extGCD(a, b) {
    if (b === 0) return { gcd: a, x: 1, y: 0 };
    const res = extGCD(b, a % b);
    return { gcd: res.gcd, x: res.y, y: res.x - Math.floor(a / b) * res.y };
  }

  function modExp(base, exp, mod) {
    let res = 1n, b = BigInt(base) % BigInt(mod), e = BigInt(exp), m = BigInt(mod);
    while (e > 0n) {
      if (e % 2n === 1n) res = (res * b) % m;
      b = (b * b) % m;
      e = e / 2n;
    }
    return Number(res);
  }

  function update() {
    const p = parseInt(pEl.value, 10), q = parseInt(qEl.value, 10);
    const e = parseInt(eEl.value, 10), m = parseInt(msgEl.value, 10);

    if (isNaN(p) || isNaN(q) || isNaN(e) || isNaN(m) || p <= 1 || q <= 1 || p === q || e <= 1 || m < 0) return;

    const n = p * q;
    const phi = (p - 1) * (q - 1);

    const { gcd, x } = extGCD(e, phi);
    if (gcd !== 1) {
      cResEl.textContent = 'INVALID EXPONENT e (gcd(e, φ(n)) = ' + gcd + ' ≠ 1)';
      kResEl.textContent = 'e must be coprime to φ(n) = ' + phi;
      return;
    }

    const d = ((x % phi) + phi) % phi;

    if (m >= n) {
      cResEl.textContent = 'MESSAGE m MUST BE LESS THAN n (' + m + ' ≥ ' + n + ')';
      kResEl.textContent = 'Split large messages into chunks smaller than n';
      return;
    }

    // Encrypt: c = m^e mod n
    const c = modExp(m, e, n);
    // Decrypt: m_dec = c^d mod n
    const m_dec = modExp(c, d, n);

    cResEl.textContent = 'Ciphertext c = ' + c + ' | Decrypted m = ' + m_dec + (m_dec === m ? ' ✓' : ' ✗');
    kResEl.textContent = 'Public Key: (e=' + e + ', n=' + n + ') | Private Key: (d=' + d + ', n=' + n + ') | Modulus n = ' + n + ', φ(n) = ' + phi;
  }

  [pEl, qEl, eEl, msgEl].forEach(el => el.addEventListener('input', update));
  update();
})();

rsa-modular-exponentiation-key-generatio.js:
(() => {
  'use strict';
  const pEl = document.getElementById('rsa-p'), qEl = document.getElementById('rsa-q');
  const eEl = document.getElementById('rsa-e'), mEl = document.getElementById('rsa-m');
  const kResEl = document.getElementById('rsa-res-keys'), cResEl = document.getElementById('rsa-res-cipher');

  // Extended Euclidean algorithm for modular inverse
  function modInverse(a, m) {
    let m0 = m, t, q;
    let x0 = 0, x1 = 1;
    if (m === 1) return 0;
    while (a > 1) {
      q = Math.floor(a / m);
      t = m;
      m = a % m;
      a = t;
      t = x0;
      x0 = x1 - q * x0;
      x1 = t;
    }
    if (x1 < 0) x1 += m0;
    return x1;
  }

  // Modular exponentiation (base^exp mod mod)
  function powerMod(base, exp, mod) {
    let res = 1;
    base = base % mod;
    while (exp > 0) {
      if (exp % 2 === 1) res = (res * base) % mod;
      base = (base * base) % mod;
      exp = Math.floor(exp / 2);
    }
    return res;
  }

  function gcd(a, b) {
    return b === 0 ? a : gcd(b, a % b);
  }

  function update() {
    const p = parseInt(pEl.value, 10), q = parseInt(qEl.value, 10);
    const e = parseInt(eEl.value, 10), m = parseInt(mEl.value, 10);

    if (isNaN(p) || isNaN(q) || isNaN(e) || isNaN(m) || p <= 1 || q <= 1 || p === q || m < 0) return;

    // Modulus n = p * q
    const n = p * q;
    // Euler totient phi(n) = (p - 1) * (q - 1)
    const phi = (p - 1) * (q - 1);

    if (gcd(e, phi) !== 1) {
      kResEl.textContent = 'Invalid e: gcd(e, φ(n)) must be 1!';
      return;
    }

    // Private key d = e^-1 mod phi
    const d = modInverse(e, phi);

    // Encrypt ciphertext c = m^e mod n
    const c = powerMod(m, e, n);

    // Decrypt decrypted = c^d mod n
    const decrypted = powerMod(c, d, n);

    kResEl.textContent = 'Public (e=' + e + ', n=' + n + ') | Private d = ' + d + ' (φ = ' + phi + ')';
    cResEl.textContent = 'Ciphertext c = ' + c + ' | Decrypted: ' + decrypted + ' (Match: ' + (decrypted === m ? 'VERIFIED OK' : 'FAIL') + ')';
  }

  [pEl, qEl, eEl, mEl].forEach(el => el.addEventListener('input', update));
  update();
})();

rsa-public-private-key-math-calculator.js:
(() => {
  'use strict';
  const pEl = document.getElementById('rsa-p'), qEl = document.getElementById('rsa-q');
  const eEl = document.getElementById('rsa-e'), mEl = document.getElementById('rsa-m');
  const cResEl = document.getElementById('rsa-res-ciph'), kResEl = document.getElementById('rsa-res-keys');

  function modExp(base, exp, mod) {
    let res = 1n;
    base = base % mod;
    while (exp > 0n) {
      if (exp % 2n === 1n) res = (res * base) % mod;
      exp = exp / 2n;
      base = (base * base) % mod;
    }
    return res;
  }

  function modInverse(e, phi) {
    let [m0, y, x] = [phi, 0n, 1n];
    if (phi === 1n) return 0n;
    while (e > 1n) {
      if (phi === 0n) return null;
      let q = e / phi;
      let t = phi;
      phi = e % phi;
      e = t;
      t = y;
      y = x - q * y;
      x = t;
    }
    if (x < 0n) x += m0;
    return x;
  }

  function update() {
    try {
      const p = BigInt(pEl.value), q = BigInt(qEl.value);
      const e = BigInt(eEl.value), M = BigInt(mEl.value);

      if (p <= 1n || q <= 1n || p === q || e <= 1n || M < 0n) return;

      const n = p * q;
      const phi = (p - 1n) * (q - 1n);
      const d = modInverse(e, phi);
      if (!d) {
        cResEl.textContent = 'Error: e is not coprime to φ(n)';
        return;
      }

      const C = modExp(M, e, n);
      const M_dec = modExp(C, d, n);

      cResEl.textContent = 'Ciphertext C = ' + C.toString() + ' (Decrypted: ' + M_dec.toString() + ')';
      kResEl.textContent = 'Public (n=' + n.toString() + ', e=' + e.toString() + ') | Private d=' + d.toString() + ' (φ=' + phi.toString() + ')';
    } catch (err) {}
  }

  [pEl, qEl, eEl, mEl].forEach(el => el.addEventListener('input', update));
  update();
})();

