  const enResEl = document.getElementById('pib-res-en'), jResEl = document.getElementById('pib-res-joules');

  const hPlanck = 6.62607015e-34;
  const mElectron = 9.1093837e-31;
  const eVToJ = 1.602176634e-19;

  function update() {
