    const energyEv = energyJ / eVToJ;

    enResEl.textContent = energyEv >= 1000 ? (energyEv / 1000).toFixed(2) + ' keV' : energyEv.toFixed(3) + ' eV';
    jResEl.textContent = energyJ.toExponential(2) + ' Joules (n = ' + n + ')';
  }

