(() => {
  'use strict';
  const pEl = document.getElementById('sc-p'), cnEl = document.getElementById('sc-cn');
  const qResEl = document.getElementById('sc-res-q'), sResEl = document.getElementById('sc-res-s');

  function update() {
    const P_mm = parseFloat(pEl.value), CN = parseFloat(cnEl.value);
    if (isNaN(P_mm) || isNaN(CN) || P_mm <= 0 || CN <= 30 || CN >= 100) return;

    // Maximum potential retention: S = (25400 / CN) - 254  [mm]
    const S_mm = (25400.0 / CN) - 254.0;

    // Initial abstraction: Ia = 0.2 * S  [mm]
    const Ia_mm = 0.20 * S_mm;

    if (P_mm <= Ia_mm) {
      qResEl.textContent = 'Direct Runoff Q = 0.0 mm (0%)';
      qResEl.style.color = '#22543d';
      sResEl.textContent = 'All rainfall absorbed by soil/canopy (P = ' + P_mm + ' mm ≤ Initial Abstraction I_a = ' + Ia_mm.toFixed(1) + ' mm)';
      return;
    }

    // Direct runoff depth: Q = (P - 0.2*S)^2 / (P + 0.8*S)  [mm]
    const Q_mm = Math.pow(P_mm - Ia_mm, 2) / (P_mm + (0.80 * S_mm));
    const runoff_pct = (Q_mm / P_mm) * 100.0;

    qResEl.textContent = 'Direct Runoff Q = ' + Q_mm.toFixed(1) + ' mm (' + runoff_pct.toFixed(1) + '% of storm)';
    qResEl.style.color = '#22543d';
    sResEl.textContent = 'Soil Retention S = ' + S_mm.toFixed(1) + ' mm | Initial Abstraction I_a = ' + Ia_mm.toFixed(1) + ' mm (CN = ' + CN + ')';
  }

  pEl.addEventListener('input', update);
  cnEl.addEventListener('input', update);
  update();
})();

searching-visualizer.js:
﻿(function(){
'use strict';
const cv=document.getElementById('search-canvas'),ctx=cv.getContext('2d');
const msg=document.getElementById('search-msg'),searchBtn=document.getElementById('search-btn'),
      newBtn=document.getElementById('new-arr-btn'),targetIn=document.getElementById('target-input'),
      typeSel=document.getElementById('search-type'),spd=document.getElementById('spd');
let arr=[],searching=false;

function resize(){cv.width=cv.clientWidth*devicePixelRatio;cv.height=cv.clientHeight*devicePixelRatio;ctx.scale(devicePixelRatio,devicePixelRatio);}
window.addEventListener('resize',()=>{resize();draw();});resize();

function gen(){
  arr=[];for(let i=0;i<25;i++)arr.push(Math.floor(Math.random()*99)+1);
  draw();msg.textContent='Array ready. Pick a target and press Search.';
}
function draw(hl={}){
  const W=cv.clientWidth,H=cv.clientHeight,n=arr.length,bw=W/n;
  ctx.clearRect(0,0,W,H);
  for(let i=0;i<n;i++){
    let c='#4fc3f7';
    if(hl.checked&&hl.checked.has(i))c='#90a4ae';
    if(hl.current===i)c='#ef5350';
    if(hl.found===i)c='#66bb6a';
    if(hl.range&&hl.range.has(i))c='#ffd54f';
    ctx.fillStyle=c;
    const bh=(arr[i]/100)*(H-50);
    ctx.fillRect(i*bw+2,H-30-bh,bw-4,bh);
    ctx.fillStyle='#eee';ctx.font='11px sans-serif';ctx.textAlign='center';
    ctx.fillText(arr[i],i*bw+bw/2,H-10);
  }
}
function sleep(){return new Promise(r=>setTimeout(r,500-(+spd.value)*4.5));}

async function linearSearch(t){
  const checked=new Set();
  for(let i=0;i<arr.length;i++){
    if(!searching)return;
    draw({checked,current:i});await sleep();
    if(arr[i]===t){draw({found:i});msg.textContent='✓ Found '+t+' at index '+i+' after '+(i+1)+' comparisons!';return;}
    checked.add(i);
  }
  msg.textContent='✗ '+t+' not found after '+arr.length+' comparisons.';
}
async function binarySearch(t){
  arr.sort((a,b)=>a-b);draw();
  await sleep();
  let lo=0,hi=arr.length-1,steps=0;
  while(lo<=hi&&searching){
    const mid=Math.floor((lo+hi)/2);steps++;
    const range=new Set();for(let x=lo;x<=hi;x++)range.add(x);
    draw({range,current:mid});await sleep();
    if(arr[mid]===t){draw({found:mid});msg.textContent='✓ Found '+t+' at index '+mid+' in '+steps+' steps (Binary Search)!';return;}
    if(arr[mid]<t)lo=mid+1;else hi=mid-1;
  }
  msg.textContent='✗ '+t+' not found after '+steps+' steps.';
}

searchBtn.addEventListener('click',async()=>{
  if(searching){searching=false;searchBtn.textContent='🔍 Search';return;}
  const t=parseInt(targetIn.value);
  if(isNaN(t)){msg.textContent='Enter a valid target number.';return;}
  searching=true;searchBtn.textContent='⏹ Stop';
  msg.textContent='Searching for '+t+'...';
  if(typeSel.value==='linear')await linearSearch(t);
  else await binarySearch(t);
  searching=false;searchBtn.textContent='🔍 Search';
});
newBtn.addEventListener('click',()=>{if(!searching)gen();});
typeSel.addEventListener('change',()=>{
  if(typeSel.value==='binary'){arr.sort((a,b)=>a-b);draw();msg.textContent='Array sorted for Binary Search.';}
});
gen();
})();

secant-method-numerical-root-finding-cal.js:
(() => {
  'use strict';
  const fnEl = document.getElementById('sc-fn'), x0El = document.getElementById('sc-x0'), x1El = document.getElementById('sc-x1');
  const rtResEl = document.getElementById('sc-res-root'), itResEl = document.getElementById('sc-res-iter');

  function evalF(type, x) {
    if (type === 'x3_x_2') return Math.pow(x, 3) - x - 2;
    if (type === 'cos_x') return Math.cos(x) - x;
    return Math.pow(x, 2) - 7;
  }

  function update() {
    const fnType = fnEl.value;
    let x_prev = parseFloat(x0El.value), x_curr = parseFloat(x1El.value);

    if (isNaN(x_prev) || isNaN(x_curr) || x_prev === x_curr) return;

    let iter = 0;
    const maxIter = 50, tol = 1e-7;

    while (iter < maxIter) {
      const f_prev = evalF(fnType, x_prev);
      const f_curr = evalF(fnType, x_curr);

      if (Math.abs(f_curr - f_prev) < 1e-12) break;

      const x_next = x_curr - f_curr * ((x_curr - x_prev) / (f_curr - f_prev));

      if (Math.abs(x_next - x_curr) < tol) {
        x_curr = x_next;
        break;
      }

      x_prev = x_curr;
      x_curr = x_next;
      iter++;
    }

    rtResEl.textContent = 'Root x* ≈ ' + x_curr.toFixed(6);
    itResEl.textContent = 'Converged in ' + iter + ' secant iterations (f(x*) = ' + evalF(fnType, x_curr).toExponential(2) + ' | No derivatives required)';
  }

  [fnEl, x0El, x1El].forEach(el => el.addEventListener('input', update));
  fnEl.addEventListener('change', update);
  update();
})();

second-order-ode-damping-ratio-natural-f.js:
(() => {
  'use strict';
  const zEl = document.getElementById('so-zeta'), wEl = document.getElementById('so-wn');
  const osResEl = document.getElementById('so-res-os'), tmResEl = document.getElementById('so-res-time');

  function update() {
    const zeta = parseFloat(zEl.value), wn = parseFloat(wEl.value);
    if (isNaN(zeta) || isNaN(wn) || zeta < 0 || wn <= 0) return;

    let os_pct = 0, ts_s = 0, tp_s = 0, wd = 0, regime = '';
    let color = '#22543d';

    if (zeta < 1.0) {
      // Underdamped
      wd = wn * Math.sqrt(1.0 - Math.pow(zeta, 2));
      // %OS = exp( -pi * zeta / sqrt(1 - zeta^2) ) * 100
      os_pct = Math.exp((-Math.PI * zeta) / Math.sqrt(1.0 - Math.pow(zeta, 2))) * 100.0;
      tp_s = Math.PI / wd;
      ts_s = 4.0 / (zeta * wn);
      regime = 'UNDERDAMPED (0 < ζ < 1: Oscillatory transient with overshoot)';
      color = '#22543d';
    } else if (zeta === 1.0) {
      // Critically damped
      os_pct = 0.0;
      ts_s = 5.83 / wn;
      regime = 'CRITICALLY DAMPED (ζ = 1.0: Fastest response without overshoot)';
      color = '#22543d';
    } else {
      // Overdamped
      os_pct = 0.0;
      const s1 = -wn * (zeta - Math.sqrt(Math.pow(zeta, 2) - 1.0));
      ts_s = 4.0 / Math.abs(s1);
      regime = 'OVERDAMPED (ζ > 1: Sluggish non-oscillatory return to equilibrium)';
      color = '#2563eb';
    }

    osResEl.textContent = 'Overshoot %OS = ' + os_pct.toFixed(2) + '% (' + regime.split(' (')[0] + ')';
    osResEl.style.color = color;
    tmResEl.textContent = 'Settling Time t_s = ' + ts_s.toFixed(2) + ' s | ' + (zeta < 1 ? 'Peak Time t_p = ' + tp_s.toFixed(2) + ' s | Damped ω_d = ' + wd.toFixed(2) + ' rad/s' : 'No Oscillation (Real Poles)');
    tmResEl.style.color = color;
  }

  zEl.addEventListener('input', update);
  wEl.addEventListener('input', update);
  update();
})();

