(() => {
  'use strict';
  const p0El = document.getElementById('sel-p0'), sEl = document.getElementById('sel-s'), genEl = document.getElementById('sel-gen');
  const ptResEl = document.getElementById('sel-res-pt'), fxResEl = document.getElementById('sel-res-fix');

  function update() {
    const p0 = parseFloat(p0El.value), s = parseFloat(sEl.value), tGen = parseInt(genEl.value, 10);
    if (isNaN(p0) || isNaN(s) || isNaN(tGen) || p0 <= 0 || p0 >= 1.0 || tGen < 0) return;

    // Discrete generation simulation of natural selection for dominant/haploid allele:
    // p_(t+1) = p_t * (1 + s) / ( 1 + s * p_t )
    let p_curr = p0;
    for (let g = 1; g <= tGen; g++) {
      p_curr = (p_curr * (1.0 + s)) / (1.0 + (s * p_curr));
    }

    // Time to 99% fixation approximation: t_fix approx = (2 / s) * ln( (1 - p0) / p0 )
    let t_fix_str = '';
    if (s > 0) {
      const t_fix = (1.0 / s) * Math.log((0.99 / (1.0 - 0.99)) / (p0 / (1.0 - p0)));
      t_fix_str = '~' + Math.round(t_fix) + ' Generations to reach 99% Selective Fixation';
    } else if (s < 0) {
      t_fix_str = 'Negative Selection: Allele purged toward extinction (p -> 0)';
    } else {
      t_fix_str = 'Neutral Evolution (s = 0): Governed purely by genetic drift';
    }

    ptResEl.textContent = 'p(' + tGen + ') = ' + p_curr.toFixed(3) + ' (' + (p_curr * 100).toFixed(1) + '% Frequency)';
    fxResEl.textContent = t_fix_str + ' (Relative Fitness W = ' + (1 + s).toFixed(2) + ' vs Baseline 1.00)';
  }

  [p0El, sEl, genEl].forEach(el => el.addEventListener('input', update));
  update();
})();

semi-empirical-mass-formula-weizsacker-l.js:
(() => {
  'use strict';
  const aEl = document.getElementById('ld-a'), zEl = document.getElementById('ld-z');
  const bResEl = document.getElementById('ld-res-b'), trResEl = document.getElementById('ld-res-terms');

  // Standard Weizsäcker coefficients in MeV:
  const a_v = 15.67; // Volume
  const a_s = 17.23; // Surface
  const a_c = 0.714; // Coulomb
  const a_a = 23.28; // Asymmetry
  const a_p = 12.00; // Pairing

  function update() {
    const A = parseInt(aEl.value, 10), Z = parseInt(zEl.value, 10);
    if (isNaN(A) || isNaN(Z) || A <= 0 || Z <= 0 || Z > A) return;

    const N = A - Z;

    // Terms:
    const E_vol = a_v * A;
    const E_surf = - a_s * Math.pow(A, 2.0 / 3.0);
    const E_coul = - a_c * (Z * (Z - 1)) / Math.pow(A, 1.0 / 3.0);
    const E_asym = - a_a * Math.pow(A - (2.0 * Z), 2) / A;

    // Pairing term delta:
    let delta = 0;
    if (Z % 2 === 0 && N % 2 === 0) delta = + a_p / Math.sqrt(A); // Even-even
    else if (Z % 2 !== 0 && N % 2 !== 0) delta = - a_p / Math.sqrt(A); // Odd-odd
    else delta = 0.0; // Even-odd

    const B_MeV = E_vol + E_surf + E_coul + E_asym + delta;
    const BE_A = B_MeV / A;

    bResEl.textContent = 'Binding Energy B = ' + B_MeV.toFixed(1) + ' MeV (' + BE_A.toFixed(2) + ' MeV/Nucleon)';
    trResEl.textContent = 'Vol: +' + E_vol.toFixed(1) + ' | Surf: ' + E_surf.toFixed(1) + ' | Coul: ' + E_coul.toFixed(1) + ' | Asym: ' + E_asym.toFixed(1) + ' | Pair: ' + (delta >= 0 ? '+' : '') + delta.toFixed(1) + ' MeV';
  }

  aEl.addEventListener('input', update);
  zEl.addEventListener('input', update);
  update();
})();

