  'use strict';
  const gwEl = document.getElementById('pr-gwet'), wEl = document.getElementById('pr-w'), maxEl = document.getElementById('pr-max');
  const gdResEl = document.getElementById('pr-res-gd'), rcResEl = document.getElementById('pr-res-rc');

  function update() {
    const gamma_wet = parseFloat(gwEl.value), w_pct = parseFloat(wEl.value), gamma_d_max = parseFloat(maxEl.value);
    if (isNaN(gamma_wet) || isNaN(w_pct) || isNaN(gamma_d_max) || gamma_wet <= 0 || w_pct < 0 || gamma_d_max <= 0) return;

    const w_dec = w_pct / 100.0;

    // Dry density: gamma_d = gamma_wet / ( 1 + w )  [kN / m^3]
    const gamma_d = gamma_wet / (1.0 + w_dec);

    // Relative compaction: RC = ( gamma_d / gamma_d_max ) * 100  [%]
    const RC = (gamma_d / gamma_d_max) * 100.0;

    let passStatus = '', color = '#22543d';
    if (RC >= 95.0) {
      passStatus = 'PASSES SPECIFICATION (RC = ' + RC.toFixed(1) + '% ≥ 95.0%: High structural stability)';
      color = '#22543d';
    } else {
      passStatus = 'FAILS (RC = ' + RC.toFixed(1) + '% < 95.0%: Additional roller compaction passes required!)';
      color = '#c53030';
    }

    gdResEl.textContent = 'Dry Density γ_d = ' + gamma_d.toFixed(2) + ' kN / m³';
    rcResEl.textContent = 'Relative Compaction RC = ' + RC.toFixed(1) + '% | ' + passStatus + ' (w = ' + w_pct + '%)';
    rcResEl.style.color = color;
  }

  [gwEl, wEl, maxEl].forEach(el => el.addEventListener('input', update));
  update();
})();

soil-moisture-content-degree-of-saturati.js:
(() => {
  'use strict';
  const mtotEl = document.getElementById('sm-mtot'), mdryEl = document.getElementById('sm-mdry');
  const eEl = document.getElementById('sm-e'), gsEl = document.getElementById('sm-gs');
  const srResEl = document.getElementById('sm-res-sr'), wResEl = document.getElementById('sm-res-w');

  function update() {
    const M_tot = parseFloat(mtotEl.value), M_dry = parseFloat(mdryEl.value);
    const e = parseFloat(eEl.value), G_s = parseFloat(gsEl.value);

    if (isNaN(M_tot) || isNaN(M_dry) || isNaN(e) || isNaN(G_s) || M_tot < M_dry || M_dry <= 0 || e <= 0 || G_s <= 0) return;

    // Water mass Mw = M_tot - M_dry
    const M_w = M_tot - M_dry;

    // Gravimetric water content: w = (M_w / M_dry) * 100%
    const w = M_w / M_dry;
    const w_pct = w * 100.0;

    // Degree of saturation: S_r = ( w * G_s ) / e
    const S_r = (w * G_s) / e;
    const S_r_pct = Math.min(100.0, S_r * 100.0);

    // Volumetric water content: theta = S_r * n = S_r * (e / (1+e))
    const n = e / (1.0 + e);
    const theta_pct = (S_r * n) * 100.0;

    let state = '';
    if (S_r_pct >= 99.0) state = 'FULLY SATURATED (S_r = 100%: All void space filled with water)';
    else if (S_r_pct >= 80.0) state = 'VERY MOIST (80% - 99%)';
    else if (S_r_pct >= 50.0) state = 'PARTIALLY SATURATED (50% - 79%)';
    else state = 'RELATIVELY DRY (S_r < 50%)';

    srResEl.textContent = 'Saturation S_r = ' + S_r_pct.toFixed(1) + '%';
    wResEl.textContent = 'Water Content w = ' + w_pct.toFixed(1) + '% | Volumetric θ = ' + theta_pct.toFixed(2) + '% (' + state + ')';
  }

  [mtotEl, mdryEl, eEl, gsEl].forEach(el => el.addEventListener('input', update));
  update();
})();

