  const h0El = document.getElementById('cs-h0'), e0El = document.getElementById('cs-e0');
  const ccEl = document.getElementById('cs-cc'), s0El = document.getElementById('cs-s0'), dsEl = document.getElementById('cs-ds');
  const scResEl = document.getElementById('cs-res-sc'), stResEl = document.getElementById('cs-res-strain');

  function update() {
    const H0 = parseFloat(h0El.value), e0 = parseFloat(e0El.value);
    const Cc = parseFloat(ccEl.value), s0 = parseFloat(s0El.value), ds = parseFloat(dsEl.value);

    if (isNaN(H0) || isNaN(e0) || isNaN(Cc) || isNaN(s0) || isNaN(ds) || H0 <= 0 || e0 <= 0 || Cc <= 0 || s0 <= 0 || ds <= 0) return;

    const Sc_m = ((Cc * H0) / (1 + e0)) * Math.log10((s0 + ds) / s0);
    const Sc_mm = Sc_m * 1000;
    const Sc_cm = Sc_m * 100;

    const vertStrainPct = (Sc_m / H0) * 100;
    const delta_e = Cc * Math.log10((s0 + ds) / s0);
    const e_final = e0 - delta_e;

    scResEl.textContent = Sc_mm.toFixed(1) + ' mm (' + Sc_cm.toFixed(1) + ' cm Settlement)';
    stResEl.textContent = vertStrainPct.toFixed(2) + '% Vertical Strain (Final Void Ratio e_f = ' + e_final.toFixed(3) + ')';
  }

  [h0El, e0El, ccEl, s0El, dsEl].forEach(el => el.addEventListener('input', update));
  update();
})();

soil-porosity-void-ratio-bulk-density-ph.js:
(() => {
  'use strict';
  const gsEl = document.getElementById('sp-gs'), eEl = document.getElementById('sp-e'), wEl = document.getElementById('sp-w');
  const dnResEl = document.getElementById('sp-res-dens'), prResEl = document.getElementById('sp-res-por');

  const gamma_w = 9.80665; // kN / m^3

  function update() {
    const G_s = parseFloat(gsEl.value), e = parseFloat(eEl.value), w_pct = parseFloat(wEl.value);
    if (isNaN(G_s) || isNaN(e) || isNaN(w_pct) || G_s <= 0 || e <= 0 || w_pct < 0) return;

    const w = w_pct / 100.0;

    // Porosity: n = e / (1 + e)
    const n = e / (1.0 + e);
    const n_pct = n * 100.0;

    // Dry unit weight: gamma_d = G_s * gamma_w / (1 + e)
    const gamma_d = (G_s * gamma_w) / (1.0 + e);

    // Total moist unit weight: gamma = gamma_d * (1 + w)
    const gamma_moist = gamma_d * (1.0 + w);

    // Saturated unit weight (Sr = 1.0): gamma_sat = (G_s + e) * gamma_w / (1 + e)
    const gamma_sat = ((G_s + e) * gamma_w) / (1.0 + e);

    // Submerged buoyant unit weight: gamma_prime = gamma_sat - gamma_w
    const gamma_prime = gamma_sat - gamma_w;

    // Degree of saturation: S_r = w * G_s / e
    const S_r_pct = (w * G_s / e) * 100.0;

    dnResEl.textContent = 'Moist Bulk γ = ' + gamma_moist.toFixed(2) + ' kN/m³ (Dry γ_d = ' + gamma_d.toFixed(2) + ' kN/m³)';
    prResEl.textContent = 'Porosity n = ' + n_pct.toFixed(2) + '% | γ_sat = ' + gamma_sat.toFixed(2) + ' kN/m³ | γ' = ' + gamma_prime.toFixed(2) + ' kN/m³ (S_r = ' + S_r_pct.toFixed(1) + '%)';
  }

  [gsEl, eEl, wEl].forEach(el => el.addEventListener('input', update));
  update();
})();

soil-slope-stability-bishop-simplified-m.js:
(() => {
  'use strict';
  const cEl = document.getElementById('slp-c'), phiEl = document.getElementById('slp-phi');
  const hEl = document.getElementById('slp-h'), bEl = document.getElementById('slp-beta'), ruEl = document.getElementById('slp-ru');
  const fsResEl = document.getElementById('slp-res-fs'), stResEl = document.getElementById('slp-res-stat');

  const gamma_soil = 19.0; // kN / m^3

  function update() {
    const c = parseFloat(cEl.value), phiDeg = parseFloat(phiEl.value);
    const H = parseFloat(hEl.value), betaDeg = parseFloat(bEl.value), ru = parseFloat(ruEl.value);

    if (isNaN(c) || isNaN(phiDeg) || isNaN(H) || isNaN(betaDeg) || isNaN(ru) || H <= 0 || betaDeg <= 0 || betaDeg >= 90) return;

    const phiRad = (phiDeg * Math.PI) / 180;
    const betaRad = (betaDeg * Math.PI) / 180;

    // Dimensionless stability number Taylor/Bishop correlation:
    // N_s = c / (gamma * H)
    const N_s = c / (gamma_soil * H);

    // Friction term component:
    const tanPhi = Math.tan(phiRad);
    const tanBeta = Math.tan(betaRad);

    // Bishop circular slip approximation:
    // FS approx = ( (c / (gamma * H * sin(beta)*cos(beta))) + (tan(phi)/tan(beta)) * (1 - ru / cos^2(beta)) )
    const termCohesion = c / (gamma_soil * H * Math.sin(betaRad) * Math.cos(betaRad));
    const termFriction = (tanPhi / tanBeta) * (1.0 - (ru / Math.pow(Math.cos(betaRad), 2)));
    const FS = termCohesion + Math.max(0, termFriction);

    let status = '';
    let color = '#22543d';

    if (FS >= 1.50) {
      status = 'STABLE (FS = ' + FS.toFixed(2) + ' ≥ 1.50: Meets highway embankment & civil engineering safety standard)';
      color = '#22543d';
    } else if (FS >= 1.00) {
      status = 'MARGINALLY STABLE (1.00 ≤ FS < 1.50: Risk of creep or rain-induced landslide triggering)';
      color = '#d97706';
    } else {
      status = 'UNSTABLE / ACTIVE FAILURE (FS < 1.00: Slope undergoes catastrophic rotational shear collapse!)';
      color = '#c53030';
    }

    fsResEl.textContent = 'FS = ' + FS.toFixed(2);
    fsResEl.style.color = color;
    stResEl.textContent = status + ' | Cohesion Contribution: +' + termCohesion.toFixed(2) + ', Friction: +' + termFriction.toFixed(2);
  }

  [cEl, phiEl, hEl, bEl, ruEl].forEach(el => el.addEventListener('input', update));
  update();
})();

soil-swell-shrinkage-factor-calculator.js:
(() => {
  'use strict';
  const sEl = document.getElementById('sw-soil'), bEl = document.getElementById('sw-bcy');
  const lResEl = document.getElementById('sw-res-lcy'), cResEl = document.getElementById('sw-res-ccy');

  function update() {
    const [swStr, shStr] = sEl.value.split(',');
    const swellPct = parseFloat(swStr), shrinkPct = parseFloat(shStr);
    const bcy = parseFloat(bEl.value);

    if (isNaN(bcy) || bcy <= 0) return;

    // LCY = BCY * (1 + swell / 100)
    const lcy = bcy * (1 + (swellPct / 100));
    // CCY = BCY * (1 - shrink / 100)
    const ccy = bcy * (1 - (shrinkPct / 100));

    lResEl.textContent = Math.round(lcy).toLocaleString() + ' LCY (Loose Haul)';
    cResEl.textContent = Math.round(ccy).toLocaleString() + ' CCY (Finished Embankment Fill)';
  }

  sEl.addEventListener('change', update);
  bEl.addEventListener('input', update);
  update();
})();

soil-uscs-soil-classification-liquid-pla.js:
(() => {
  'use strict';
  const llEl = document.getElementById('sc-ll'), plEl = document.getElementById('sc-pl');
  const uscsResEl = document.getElementById('sc-res-uscs'), piResEl = document.getElementById('sc-res-pi');

  function update() {
    const LL = parseFloat(llEl.value), PL = parseFloat(plEl.value);
    if (isNaN(LL) || isNaN(PL) || LL <= 0 || PL < 0 || LL <= PL) return;

    // Plasticity Index: PI = LL - PL
    const PI = LL - PL;

    // Casagrande A-Line equation: PI_A = 0.73 * (LL - 20)
    const PI_A_line = 0.73 * (LL - 20.0);

    let symbol = '', name = '', color = '#22543d';

    if (LL < 50.0) {
      // Low Plasticity (L)
      if (PI > PI_A_line && PI > 7.0) {
        symbol = 'CL';
        name = 'LEAN CLAY (Low to medium plasticity, above A-line)';
        color = '#22543d';
      } else if (PI < PI_A_line || PI < 4.0) {
        symbol = 'ML';
        name = 'SILT (Low plasticity inorganic silt, below A-line)';
        color = '#2563eb';
      } else {
        symbol = 'CL-ML';
        name = 'SILTY CLAY (Dual classification: 4 ≤ PI ≤ 7)';
        color = '#d97706';
      }
    } else {
      // High Plasticity (H)
      if (PI > PI_A_line) {
        symbol = 'CH';
        name = 'FAT CLAY (High plasticity expansive clay, above A-line)';
        color = '#c53030';
      } else {
        symbol = 'MH';
        name = 'ELASTIC SILT (High plasticity inorganic silt, below A-line)';
        color = '#ea580c';
      }
    }

    uscsResEl.textContent = symbol + ' - ' + name.split(' (')[0];
    uscsResEl.style.color = color;
    piResEl.textContent = 'Plasticity Index PI = ' + PI.toFixed(1) + '% | A-Line = ' + PI_A_line.toFixed(2) + '% (' + (PI > PI_A_line ? 'Above A-Line' : 'Below A-Line') + ' @ LL = ' + LL + '%)';
  }

  llEl.addEventListener('input', update);
  plEl.addEventListener('input', update);
  update();
})();

soil-void-ratio-porosity-calculator.js:
(() => {
  'use strict';
  const eEl = document.getElementById('sp-e'), nEl = document.getElementById('sp-n');
  const dResEl = document.getElementById('sp-res-desc'), vsResEl = document.getElementById('sp-res-vs');

  function updateFromE(e) {
    if (isNaN(e) || e <= 0) return;

    // n = e / (1 + e)
    const n = e / (1 + e);
    const nPct = n * 100;
    nEl.value = nPct.toFixed(1);

    vsResEl.textContent = ((1 - n) * 100).toFixed(1) + '% Solids Fraction';

    if (e < 0.4) dResEl.textContent = 'Dense Well-Graded Gravel / Till (e < 0.4)';
    else if (e < 0.7) dResEl.textContent = 'Medium Sand / Sandy Gravel (e = 0.4 - 0.7)';
    else if (e < 1.1) dResEl.textContent = 'Loose Sand / Silty Clay (e = 0.7 - 1.1)';
    else dResEl.textContent = 'Soft Organic Clay / Peat (e > 1.1: High Settlement)';
  }

  eEl.addEventListener('input', () => {
    const v = parseFloat(eEl.value);
    if (!isNaN(v) && v > 0) updateFromE(v);
  });

  nEl.addEventListener('input', () => {
    const nPct = parseFloat(nEl.value);
    if (!isNaN(nPct) && nPct > 0 && nPct < 100) {
      const n = nPct / 100;
      const e = n / (1 - n);
      eEl.value = e.toFixed(3);
      updateFromE(e);
    }
  });

  updateFromE(0.65);
})();

solar-battery-bank-sizing-calculator.js:
(() => {
  'use strict';
  const loadEl = document.getElementById('sb-load'), autEl = document.getElementById('sb-auton');
  const voltEl = document.getElementById('sb-volt'), dodEl = document.getElementById('sb-dod');
  const ahResEl = document.getElementById('sb-res-ah'), kwhResEl = document.getElementById('sb-res-kwh');

  function update() {
    const dailyWh = parseFloat(loadEl.value), daysAuton = parseFloat(autEl.value);
    const sysVolt = parseFloat(voltEl.value), dod = parseFloat(dodEl.value);
    if (isNaN(dailyWh) || isNaN(daysAuton) || isNaN(sysVolt) || isNaN(dod) || dailyWh <= 0 || daysAuton < 1 || sysVolt <= 0 || dod <= 0) return;

    // Total Wh needed = (Daily Wh * Autonomy Days) / (DoD * 0.90 Inverter Efficiency)
    const totalWhNeeded = (dailyWh * daysAuton) / (dod * 0.90);
    const totalAhNeeded = totalWhNeeded / sysVolt;
    const totalKwh = totalWhNeeded / 1000;

    ahResEl.textContent = totalAhNeeded.toFixed(1) + ' Ah @ ' + sysVolt + 'V';
    kwhResEl.textContent = totalKwh.toFixed(2) + ' kWh';
  }

  [loadEl, autEl, voltEl, dodEl].forEach(el => el.addEventListener('input', update));
  update();
})();

solar-battery-storage-depth-of-discharge.js:
(() => {
  'use strict';
  const kwhEl = document.getElementById('bat-kwh'), chEl = document.getElementById('bat-chem'), ldEl = document.getElementById('bat-load');
  const uResEl = document.getElementById('bat-res-use'), tResEl = document.getElementById('bat-res-time');

  const CHEMS = {
    'lifepo4': { dod: 0.90, eff: 0.95, name: 'LiFePO4' },
    'nmc':     { dod: 0.90, eff: 0.92, name: 'Lithium NMC' },
    'lead':    { dod: 0.50, eff: 0.80, name: 'Lead-Acid AGM' }
  };

  function update() {
    const kwh = parseFloat(kwhEl.value), chem = CHEMS[chEl.value], loadKw = parseFloat(ldEl.value);
    if (isNaN(kwh) || isNaN(loadKw) || kwh <= 0 || loadKw <= 0) return;

    const usableKwh = kwh * chem.dod * chem.eff;
    const runtimeHrs = usableKwh / loadKw;
    const runtimeDays = runtimeHrs / 24;

    uResEl.textContent = usableKwh.toFixed(2) + ' kWh Usable (' + ((usableKwh / kwh) * 100).toFixed(1) + '% Net Delivery)';

    let timeStr = '';
    if (runtimeDays >= 1.0) timeStr = runtimeDays.toFixed(1) + ' Days (' + runtimeHrs.toFixed(1) + ' Hours)';
    else timeStr = runtimeHrs.toFixed(1) + ' Hours';

    tResEl.textContent = timeStr + ' Backup @ ' + loadKw.toFixed(2) + ' kW Continuous Load (DoD: ' + (chem.dod*100) + '%)';
  }

  [kwhEl, ldEl].forEach(el => el.addEventListener('input', update));
  chEl.addEventListener('change', update);
  update();
})();

solar-cell-fill-factor-efficiency-open-c.js:
(() => {
  'use strict';
  const vocEl = document.getElementById('sc-voc'), iscEl = document.getElementById('sc-isc');
  const pmaxEl = document.getElementById('sc-pmax'), arEl = document.getElementById('sc-area');
  const efResEl = document.getElementById('sc-res-eff'), ffResEl = document.getElementById('sc-res-ff');

  function update() {
    const V_oc = parseFloat(vocEl.value), I_sc = parseFloat(iscEl.value);
    const P_max = parseFloat(pmaxEl.value), Area_cm2 = parseFloat(arEl.value);

    if (isNaN(V_oc) || isNaN(I_sc) || isNaN(P_max) || isNaN(Area_cm2) || V_oc <= 0 || I_sc <= 0 || P_max <= 0 || Area_cm2 <= 0) return;

    // Fill factor: FF = P_max / (V_oc * I_sc)
    const theoretical_power = V_oc * I_sc;
    const FF = P_max / theoretical_power;
    const FF_pct = FF * 100.0;

    // Standard solar irradiance: 1000 W / m^2 = 0.100 W / cm^2
    const P_in = Area_cm2 * 0.100; // Watts input

    // Efficiency: eta = P_max / P_in * 100%
    const eta_pct = (P_max / P_in) * 100.0;

    let qual = '', color = '#22543d';
    if (eta_pct >= 22.0) { qual = 'PREMIUM HIGH EFFICIENCY (TOPCon / HJT / Perovskite Tandem)'; color = '#22543d'; }
    else if (eta_pct >= 18.0) { qual = 'COMMERCIAL GRADE (Standard Mono-PERC Silicon)'; color = '#22543d'; }
    else { qual = 'LOW EFFICIENCY (Polycrystalline / Thin Film)'; color = '#ea580c'; }

    efResEl.textContent = 'Efficiency η = ' + eta_pct.toFixed(2) + '% (' + qual.split(' (')[0] + ')';
    efResEl.style.color = color;
    ffResEl.textContent = 'Fill Factor FF = ' + FF_pct.toFixed(2) + '% | V_oc·I_sc = ' + theoretical_power.toFixed(2) + ' W (Input Light = ' + P_in.toFixed(2) + ' W @ 1000 W/m²)';
  }

  [vocEl, iscEl, pmaxEl, arEl].forEach(el => el.addEventListener('input', update));
  update();
})();

solar-inverter-dc-ac-ratio-clipping-calc.js:
(() => {
  'use strict';
  const dcEl = document.getElementById('ilr-dc'), acEl = document.getElementById('ilr-ac');
  const rResEl = document.getElementById('ilr-res-ratio'), clResEl = document.getElementById('ilr-res-clip');

  function update() {
    const dcKw = parseFloat(dcEl.value), acKw = parseFloat(acEl.value);
    if (isNaN(dcKw) || isNaN(acKw) || dcKw <= 0 || acKw <= 0) return;

    const ilr = dcKw / acKw;
