      clResEl.textContent = 'Optimal Economic Sizing (ILR 1.15 - 1.35: Max energy harvest, Clipping < 1.5%)';
      clResEl.style.color = '#22543d';
    } else if (ilr <= 1.50) {
      clResEl.textContent = 'High DC Overbuild (ILR 1.35 - 1.50: Clipping ~2-5%, Good for winter/cloudy regions)';
      clResEl.style.color = '#d97706';
    } else {
      clResEl.textContent = 'Heavy Clipping Loss (ILR > 1.50: Severe midday thermal clipping > 8%)';
      clResEl.style.color = '#c53030';
    }
  }

  dcEl.addEventListener('input', update);
  acEl.addEventListener('input', update);
  update();
})();

solar-irradiance-dni-dhi-ghi-photovoltai.js:
(() => {
  'use strict';
  const dniEl = document.getElementById('sol-dni'), dhiEl = document.getElementById('sol-dhi'), zenEl = document.getElementById('sol-zen');
  const ghiResEl = document.getElementById('sol-res-ghi'), tltResEl = document.getElementById('sol-res-tilt');

  function update() {
    const DNI = parseFloat(dniEl.value), DHI = parseFloat(dhiEl.value), theta_z_deg = parseFloat(zenEl.value);
    if (isNaN(DNI) || isNaN(DHI) || isNaN(theta_z_deg) || DNI < 0 || DHI < 0 || theta_z_deg < 0 || theta_z_deg > 90) return;

    const theta_z_rad = (theta_z_deg * Math.PI) / 180.0;

    // GHI = DHI + DNI * cos(theta_z)
    const GHI = DHI + (DNI * Math.cos(theta_z_rad));
    const sunElevation = 90.0 - theta_z_deg;

    ghiResEl.textContent = 'GHI = ' + GHI.toFixed(1) + ' W / m²';
    tltResEl.textContent = 'Optimal Fixed Tilt ≈ ' + theta_z_deg.toFixed(0) + '° | Sun Elevation = ' + sunElevation.toFixed(1) + '° (Direct Beam: ' + (DNI * Math.cos(theta_z_rad)).toFixed(1) + ' W/m² + Diffuse: ' + DHI + ' W/m²)';
  }

  [dniEl, dhiEl, zenEl].forEach(el => el.addEventListener('input', update));
  update();
})();

solar-panel-output-calculator.js:
(() => {
  'use strict';
  const wEl = document.getElementById('sol-watts'), hEl = document.getElementById('sol-hours'), lEl = document.getElementById('sol-loss');
  const btn = document.getElementById('primary-action-btn'), clearBtn = document.getElementById('clear-action-btn');
  const msgEl = document.getElementById('tool-message'), resCard = document.getElementById('sol-res-card');
  const resD = document.getElementById('sol-res-daily'), resM = document.getElementById('sol-res-monthly'), resA = document.getElementById('sol-res-annual');

  function setMsg(t, e) { msgEl.textContent = t; msgEl.className = 'message' + (e ? ' error' : ' success'); }

  btn.addEventListener('click', () => {
    const watts = parseFloat(wEl.value);
    const hours = parseFloat(hEl.value);
    const eff = (parseFloat(lEl.value) || 80) / 100;

    if (isNaN(watts) || isNaN(hours) || watts <= 0 || hours <= 0) {
      setMsg('Please enter positive values for array wattage and sun hours.', true);
      resCard.style.display = 'none'; return;
    }

    const dailyKwh = (watts * hours * eff) / 1000;
    const monthlyKwh = dailyKwh * 30;
