solar-sail-radiation-pressure-accelerati.js:
(() => {
  'use strict';
  const aEl = document.getElementById('sail-area'), mEl = document.getElementById('sail-mass');
  const rEl = document.getElementById('sail-r'), dEl = document.getElementById('sail-dist');
  const fResEl = document.getElementById('sail-res-force'), acResEl = document.getElementById('sail-res-acc');

  const I0_solar = 1361.0; // W / m^2 solar constant at 1 AU
  const c_light = 299792458; // m / s

  function update() {
    const Area = parseFloat(aEl.value), Mass = parseFloat(mEl.value);
    const R = parseFloat(rEl.value), dist_au = parseFloat(dEl.value);

    if (isNaN(Area) || isNaN(Mass) || isNaN(R) || isNaN(dist_au) || Area <= 0 || Mass <= 0 || dist_au <= 0) return;

    // Solar irradiance at distance d: I = I0 / d^2  [W / m^2]
    const I_solar = I0_solar / Math.pow(dist_au, 2);

    // Radiation pressure P_rad = (1 + R) * I / c  [N / m^2 -> uN / m^2]
    const P_rad_Pa = ((1.0 + R) * I_solar) / c_light;
    const P_rad_uN = P_rad_Pa * 1e6;

    // Total thrust force F = P_rad * Area  [Newtons -> mN]
    const Force_N = P_rad_Pa * Area;
    const Force_mN = Force_N * 1000.0;

    // Acceleration a = Force / Mass  [m / s^2 -> mm / s^2]
    const a_m_s2 = Force_N / Mass;
    const a_mm_s2 = a_m_s2 * 1000.0;

    // Delta-V accumulated per day: DeltaV = a * 86,400 seconds
    const deltaV_day_m_s = a_m_s2 * 86400.0;

    fResEl.textContent = 'Force F = ' + Force_mN.toFixed(2) + ' mN (P_rad = ' + P_rad_uN.toFixed(2) + ' μN/m²)';
    acResEl.textContent = 'Acceleration a = ' + a_mm_s2.toFixed(4) + ' mm/s² (Daily Δv = +' + deltaV_day_m_s.toFixed(1) + ' m/s @ ' + dist_au + ' AU, Mass = ' + Mass + ' kg)';
  }

  [aEl, mEl, rEl, dEl].forEach(el => el.addEventListener('input', update));
  update();
})();

solar-zenith-angle-air-mass-solar-elevat.js:
(() => {
  'use strict';
  const latEl = document.getElementById('am-lat'), decEl = document.getElementById('am-dec'), omEl = document.getElementById('am-omega');
  const amResEl = document.getElementById('am-res-am'), znResEl = document.getElementById('am-res-zenith');

  function update() {
    const latDeg = parseFloat(latEl.value), decDeg = parseFloat(decEl.value), omDeg = parseFloat(omEl.value);
    if (isNaN(latDeg) || isNaN(decDeg) || isNaN(omDeg)) return;

    const latRad = (latDeg * Math.PI) / 180;
    const decRad = (decDeg * Math.PI) / 180;
    const omRad = (omDeg * Math.PI) / 180;

    // cos(theta_z) = sin(phi)*sin(delta) + cos(phi)*cos(delta)*cos(omega)
    const cos_theta_z = (Math.sin(latRad) * Math.sin(decRad)) + (Math.cos(latRad) * Math.cos(decRad) * Math.cos(omRad));

    if (cos_theta_z <= 0) {
      amResEl.textContent = 'NIGHT (Sun Below Horizon)';
      znResEl.textContent = 'Solar Elevation < 0° (Sun set)';
      return;
    }

    const theta_z_rad = Math.acos(Math.min(1.0, cos_theta_z));
    const theta_z_deg = (theta_z_rad * 180.0) / Math.PI;
    const elevation_deg = 90.0 - theta_z_deg;

    // Kasten-Young 1989 empirical air mass formula for curved atmosphere:
    // AM = 1 / [ cos(theta_z) + 0.50572 * (96.07995 - theta_z)^(-1.6364) ]
    const term = Math.pow(96.07995 - theta_z_deg, -1.6364);
    const AM = 1.0 / (cos_theta_z + (0.50572 * term));

    amResEl.textContent = 'AM = ' + AM.toFixed(2) + ' (' + (Math.abs(AM - 1.5) < 0.1 ? 'Standard Test STC AM1.5' : 'Air Mass') + ')';
    znResEl.textContent = 'Zenith θ_z = ' + theta_z_deg.toFixed(1) + '° | Elevation α = ' + elevation_deg.toFixed(1) + '° above horizon (Hour: ' + (omDeg/15).toFixed(1) + 'h from noon)';
  }

  [latEl, decEl, omEl].forEach(el => el.addEventListener('input', update));
  update();
})();

solow-swan-growth-model-steady-state-cap.js:
(() => {
  'use strict';
  const sEl = document.getElementById('sol-s'), nEl = document.getElementById('sol-n');
  const dEl = document.getElementById('sol-del'), alEl = document.getElementById('sol-al');
  const kResEl = document.getElementById('sol-res-kstar'), cResEl = document.getElementById('sol-res-cstar');

  function update() {
    const s_pct = parseFloat(sEl.value), n_pct = parseFloat(nEl.value);
    const del_pct = parseFloat(dEl.value), alpha = parseFloat(alEl.value);

    if (isNaN(s_pct) || isNaN(n_pct) || isNaN(del_pct) || isNaN(alpha) || s_pct <= 0 || del_pct <= 0 || alpha <= 0 || alpha >= 1) return;

    const s = s_pct / 100.0;
    const n = n_pct / 100.0;
    const delta = del_pct / 100.0;
    const breakeven = n + delta; // Effective depreciation rate

    // Steady-state capital per worker: s * k^alpha = breakeven * k => k^(1-alpha) = s / breakeven
    // k* = ( s / breakeven )^( 1 / (1 - alpha) )
    const k_star = Math.pow(s / breakeven, 1.0 / (1.0 - alpha));
    const y_star = Math.pow(k_star, alpha);
    const c_star = (1.0 - s) * y_star;

    // Golden Rule savings rate equals capital share alpha (s_gold = alpha)
    const s_gold_pct = alpha * 100.0;

    kResEl.textContent = 'Steady-State k* = ' + k_star.toFixed(2) + ' | Output y* = ' + y_star.toFixed(2);
    cResEl.textContent = 'Consumption c* = ' + c_star.toFixed(2) + ' | Golden Rule Savings s_gold = ' + s_gold_pct.toFixed(1) + '% (' + (s_pct < s_gold_pct ? 'Below Golden Rule' : 'Above Golden Rule') + ')';
  }

  [sEl, nEl, dEl, alEl].forEach(el => el.addEventListener('input', update));
  update();
})();

