    const F_mN = F_N * 1000.0;
    const a_mps2 = F_N / mass_kg;
    const a_um_s2 = a_mps2 * 1e6;
    const dv_per_day_mps = a_mps2 * 86400.0;

    fResEl.textContent = 'SRP Photon Force = ' + Math.round(F_uN).toLocaleString() + ' μN (' + F_mN.toFixed(3) + ' mN)';
