    const d_km = d_au * 1.495978707e8;

    pcResEl.textContent = 'Distance d = ' + (d_pc >= 1000 ? (d_pc/1000).toFixed(3) + ' kpc' : d_pc.toFixed(3) + ' Parsecs') + ' (' + d_ly.toFixed(3) + ' Light-Years)';
    auResEl.textContent = 'd = ' + Math.round(d_au).toLocaleString() + ' AU (' + d_km.toExponential(3) + ' km | p = ' + p_arcsec.toFixed(4) + ' arcsec)';
  }

  pEl.addEventListener('input', update);
  uEl.addEventListener('change', update);
  update();
})();

stellar-spectral-classification-hr-diagr.js:
(() => {
  'use strict';
  const tEl = document.getElementById('sp-temp');
  const clResEl = document.getElementById('sp-res-class'), bvResEl = document.getElementById('sp-res-bv');

  function update() {
    const T = parseFloat(tEl.value);
    if (isNaN(T) || T <= 0) return;

    // Ballesteros formula: B - V = -0.72 + 0.46 * log10(T) ... simplified empirical fit:
    // B - V approx ( 4600 * (1/(T - 500)) - 0.25 )
    let BV = (8540.0 / T) - 0.72;
    BV = Math.max(-0.35, Math.min(1.80, BV));

    let spec = '', lines = '', color = '#22543d';
    if (T >= 30000) { spec = 'O-Type (Blazing Blue Supergiant)'; lines = 'Ionized Helium (He II), Strong UV continuum'; color = '#2563eb'; }
    else if (T >= 10000) { spec = 'B-Type (Blue-White Star - Rigel/Spica)'; lines = 'Neutral Helium (He I), Strong Balmer Hydrogen'; color = '#2563eb'; }
    else if (T >= 7500) { spec = 'A-Type (White Star - Sirius/Vega)'; lines = 'Strongest Balmer Hydrogen (H-alpha, H-beta, H-gamma)'; color = '#2563eb'; }
    else if (T >= 6000) { spec = 'F-Type (Yellow-White Star - Procyon)'; lines = 'Ionized Calcium Ca II, Weakening Hydrogen'; color = '#22543d'; }
    else if (T >= 5200) { spec = 'G-Type (Yellow Dwarf - Sun / Alpha Centauri A)'; lines = 'Strong Ca II H&K lines, Neutral Metals (Fe I, Mg I)'; color = '#22543d'; }
    else if (T >= 3700) { spec = 'K-Type (Orange Star - Arcturus/Aldebaran)'; lines = 'Neutral Metal Lines Dominant, Weak Hydrogen'; color = '#ea580c'; }
    else { spec = 'M-Type (Red Dwarf / Red Supergiant - Betelgeuse/Proxima)'; lines = 'Titanium Oxide (TiO) Molecular Bands, Neutral Atoms'; color = '#c53030'; }

    clResEl.textContent = 'Spectral Class: ' + spec;
    clResEl.style.color = color;
    bvResEl.textContent = 'Color (B - V) ≈ ' + (BV >= 0 ? '+' : '') + BV.toFixed(2) + ' | Spectral Lines: ' + lines;
    bvResEl.style.color = color;
  }

  tEl.addEventListener('input', update);
  update();
})();

stepper-motor-microstepping-resolution-c.js:
(() => {
  'use strict';
  const angEl = document.getElementById('stp-ang'), ustepEl = document.getElementById('stp-ustep');
  const mechEl = document.getElementById('stp-mech'), spdEl = document.getElementById('stp-spd');
  const sResEl = document.getElementById('stp-res-steps'), fResEl = document.getElementById('stp-res-freq');

  const MECH_MM = {
    'gt2_20': 40.0,
    'gt2_16': 32.0,
    'lead_8': 8.0,
    'lead_2': 2.0
  };

  function update() {
    const stepAngle = parseFloat(angEl.value);
    const usteps = parseInt(ustepEl.value, 10);
    const mmPerRev = MECH_MM[mechEl.value];
    const speedMmS = parseFloat(spdEl.value);

    if (isNaN(stepAngle) || isNaN(usteps) || isNaN(speedMmS) || speedMmS <= 0) return;

    const fullSteps = 360 / stepAngle;
    const totalStepsPerRev = fullSteps * usteps;
    const stepsPerMm = totalStepsPerRev / mmPerRev;
    const resolutionUm = (1 / stepsPerMm) * 1000;

    const pulseHz = stepsPerMm * speedMmS;
    const pulseKhz = pulseHz / 1000;

    sResEl.textContent = stepsPerMm.toFixed(2) + ' Steps / mm (Marlin / Klipper)';
    fResEl.textContent = pulseKhz.toFixed(2) + ' kHz Pulse Rate @ ' + speedMmS.toFixed(0) + ' mm/s (Resolution: ' + resolutionUm.toFixed(2) + ' μm/step)';
  }

  [angEl, ustepEl, mechEl].forEach(el => el.addEventListener('change', update));
  spdEl.addEventListener('input', update);
  update();
})();

stepper-motor-step-angle-pulse-rate-rpm-.js:
(() => {
  'use strict';
  const stEl = document.getElementById('sm-step'), mcEl = document.getElementById('sm-micro'), ppEl = document.getElementById('sm-pps');
  const rpResEl = document.getElementById('sm-res-rpm'), rsResEl = document.getElementById('sm-res-res');

  function update() {
    const step_angle = parseFloat(stEl.value), micro = parseFloat(mcEl.value), pps = parseFloat(ppEl.value);
    if (isNaN(step_angle) || isNaN(micro) || isNaN(pps) || step_angle <= 0 || micro <= 0 || pps <= 0) return;

    // Full steps per revolution:
    const full_steps = 360.0 / step_angle;

    // Total microstep pulses per full revolution:
    const pulses_per_rev = full_steps * micro;

    // Rotational speed in RPM: RPM = (PPS * 60) / pulses_per_rev
    const rps = pps / pulses_per_rev;
    const rpm = rps * 60.0;

    // Angular resolution per microstep pulse in degrees:
    const deg_per_pulse = step_angle / micro;

    // Assuming standard 8mm lead screw (T8x8):
    const linear_feed_mm_s = rps * 8.0;

    rpResEl.textContent = 'Rotational Speed = ' + rpm.toFixed(1) + ' RPM (' + rps.toFixed(2) + ' Rev/s)';
    rsResEl.textContent = 'Resolution: ' + pulses_per_rev.toLocaleString() + ' Pulses/Rev (' + deg_per_pulse.toFixed(4) + '°/pulse) | T8 Lead Screw: ' + linear_feed_mm_s.toFixed(1) + ' mm/s';
  }

  [stEl, mcEl, ppEl].forEach(el => el.addEventListener('change', update));
  ppEl.addEventListener('input', update);
  update();
})();

stock-dividend-yield-calculator.js:
(() => {
  'use strict';
  const pEl = document.getElementById('div-price'), dpsEl = document.getElementById('div-dps'), sEl = document.getElementById('div-shares');
  const yEl = document.getElementById('div-res-yield'), aEl = document.getElementById('div-res-annual-inc'), qEl = document.getElementById('div-res-quarterly');

  function update() {
    const price = parseFloat(pEl.value), dps = parseFloat(dpsEl.value), shares = parseFloat(sEl.value);
    if (isNaN(price) || isNaN(dps) || isNaN(shares) || price <= 0 || dps < 0 || shares <= 0) return;

    const yieldPct = (dps / price) * 100;
    const annualIncome = dps * shares;
    const quarterly = annualIncome / 4;

    yEl.textContent = yieldPct.toFixed(2) + '%';
    aEl.textContent = '$' + Math.round(annualIncome).toLocaleString() + ' / yr';
    qEl.textContent = '$' + Math.round(quarterly).toLocaleString() + ' / quarter';
  }

  pEl.addEventListener('input', update);
  dpsEl.addEventListener('input', update);
  sEl.addEventListener('input', update);
  update();
})();

stock-tank-oil-initially-in-place-stoiip.js:
(() => {
  'use strict';
  const aEl = document.getElementById('st-area'), hEl = document.getElementById('st-h');
  const pEl = document.getElementById('st-phi'), swEl = document.getElementById('st-sw'), bEl = document.getElementById('st-boi');
  const sResEl = document.getElementById('st-res-stoiip'), rResEl = document.getElementById('st-res-recov');

  function update() {
    const A = parseFloat(aEl.value), h = parseFloat(hEl.value);
    const phiPct = parseFloat(pEl.value), swPct = parseFloat(swEl.value), Boi = parseFloat(bEl.value);

    if (isNaN(A) || isNaN(h) || isNaN(phiPct) || isNaN(swPct) || isNaN(Boi) || A <= 0 || h <= 0 || phiPct <= 0 || Boi <= 0) return;

    const phi = phiPct / 100;
    const Sw = swPct / 100;

    // STOIIP = (7758 * A * h * phi * (1 - Sw)) / Boi  [Stock Tank Barrels]
    const stoiipBarrels = (7758 * A * h * phi * (1 - Sw)) / Boi;
    const stoiipMmstb = stoiipBarrels / 1e6;
    const recoverableMmstb = stoiipMmstb * 0.35; // Standard 35% recovery factor

    sResEl.textContent = stoiipMmstb.toFixed(2) + ' MMSTB (Million Barrels)';
    rResEl.textContent = recoverableMmstb.toFixed(2) + ' MMSTB Recoverable (~35% Recovery Factor)';
  }

  [aEl, hEl, pEl, swEl, bEl].forEach(el => el.addEventListener('input', update));
  update();
})();
